   hints=['הקופון: ערך נקוב כפול ריבית נקובה.', 'PV: rate הוא התשואה לפדיון, nper מספר התשלומים (5), pmt הקופון ו-fv הערך הנקוב.', 'B8: השווי פחות הערך הנקוב. נכיון יוצא שלילי.'],
